import 'package:file_picker/file_picker.dart';import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../core/app_state.dart';import '../widgets/file_selector.dart';import '../widgets/result_card.dart';
class DecompressScreen extends StatelessWidget{const DecompressScreen({super.key});Future<void>out(BuildContext c)async{final p=await FilePicker.platform.saveFile(dialogTitle:'Save restored file',fileName:'restored.bin');c.read<AppState>().selectOutput(p);}@override Widget build(BuildContext c){final s=c.watch<AppState>();return Scaffold(appBar:AppBar(title:const Text('Verified decompression')),body:SingleChildScrollView(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Restore a .xaic file',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:6),const Text('The engine rejects corruption, wrong checkpoints and invalid output sizes.'),const SizedBox(height:24),FileSelector(value:s.inputPath,onChanged:s.selectInput,label:'Compressed .xaic file'),const SizedBox(height:18),OutlinedButton.icon(onPressed:()=>out(c),icon:const Icon(Icons.save),label:Text(s.outputPath??'Select restored output')),const SizedBox(height:20),if(s.processing)...[LinearProgressIndicator(value:s.progress),Text(s.status),TextButton(onPressed:s.cancel,child:const Text('Cancel'))]else FilledButton.icon(onPressed:s.inputPath!=null&&s.outputPath!=null?s.decompress:null,icon:const Icon(Icons.unarchive),label:const Text('Decompress and verify')),if(s.lastResult!=null)...[const SizedBox(height:24),ResultCard(result:s.lastResult!)] ])));}}
